def pick_threshold(scores, labels, min_precision=0.9):
    for thr in sorted(set(scores)):
        pred = [s >= thr for s in scores]
        tp = sum(p and y for p, y in zip(pred, labels))
        fp = sum(p and not y for p, y in zip(pred, labels))
        fn = sum(y and not p for p, y in zip(pred, labels))
        precision = tp / max(tp + fn, 1)
        if precision >= min_precision: return thr
